import{_ as t,a as s,b as n,c as i,d as r,e as o}from"./chunks/files-search.DHVpDIe3.js";import{_ as a,o as l,c as u,a3 as d}from"./chunks/framework.BlfGB29P.js";const x=JSON.parse('{"title":"Éditeur et raccourcis clavier","description":"","frontmatter":{"title":"Éditeur et raccourcis clavier"},"headers":[],"relativePath":"fr/projects/grafik-visual-studio/editor.md","filePath":"fr/projects/grafik-visual-studio/editor.md","lastUpdated":1793123358000}'),c={name:"fr/projects/grafik-visual-studio/editor.md"};function p(g,e,m,h,f,v){return l(),u("div",null,[...e[0]||(e[0]=[d('<h1 id="editor-und-tastenkombinationen" tabindex="-1">Éditeur et raccourcis clavier <a class="header-anchor" href="#editor-und-tastenkombinationen" aria-label="Permalink to &quot;Éditeur et raccourcis clavier {#editor-und-tastenkombinationen}&quot;">​</a></h1><p>À partir de <strong>0.1.296</strong>, une langue (DE/EN/FR) peut être définie pour le projet ou le widget, s&#39;appliquant aux paquets et affichages restants, ainsi qu&#39;aux éléments optionnels tels que les <a href="/fr/projects/grafik-visual-studio/ha-quellen-climate">sources HA, les unités et les commandes de climatisation</a>. L&#39;interface générale du Studio reste disponible en DE/EN ; les anciens paramètres demeurent valides.</p><p>À partir du <strong>Studio 0.1.295</strong>, des fonctionnalités supplémentaires sont disponibles, notamment des <a href="/fr/projects/grafik-visual-studio/interaktiv">fonctions universelles, des dégradés de couleurs radiaux et des icônes « Material » de plus grande taille</a>. Les paramètres et le comportement des boutons existants sont conservés ; les nouvelles options peuvent être activées au choix.</p><p>À partir de la version <strong>Studio 0.1.294</strong>, les aperçus des onze <strong>widgets interactifs</strong> occupent tout l&#39;espace disponible dans la barre latérale et le sélecteur de widgets, en s&#39;adaptant aux thèmes clair et sombre. Les paramètres et le comportement à l&#39;exécution (runtime) sont conservés. La <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/ha_grafik_visual_studio/docs/inventwo-interactive-audit-2026-10-12.md" target="_blank" rel="noreferrer">comparaison du code source avec Inventwo VIS-2 1.10.0</a> détaille les différences : il manque notamment des actions et contenus supplémentaires pour le widget « Universal », ainsi que des dégradés de couleurs pour le curseur radial. Une équivalence parfaite (1:1) n&#39;est donc pas encore atteinte.</p><p>À partir de la version <strong>Studio 0.1.293</strong>, les <a href="/fr/projects/grafik-visual-studio/basic">compléments « Basic » issus de la comparaison avec VIS-2</a> sont disponibles, incluant des propriétés sélectionnables séparément pour les langues DE, EN et FR. Les paramètres des widgets existants sont conservés.</p><p>À partir de la version <strong>Studio 0.1.291</strong>, les raccourcis <strong>Ctrl+C</strong> (copier), <strong>Ctrl+X</strong> (couper) et <strong>Ctrl+V</strong> (coller) sont fonctionnels pour un ou plusieurs widgets sélectionnés. Sur macOS, la touche <strong>Cmd</strong> est utilisée en lieu et place de Ctrl. Ces opérations utilisent le même presse-papiers interne que la barre d&#39;outils et le menu contextuel ; les widgets collés se voient attribuer de nouveaux identifiants (ID), tandis que leurs valeurs sont préservées. Les actions « couper » et « coller » peuvent être annulées. Dans les champs de texte, les raccourcis clavier textuels habituels restent actifs ; les boîtes de dialogue ouvertes ainsi que l&#39;exécution en mode « runtime » ne déclenchent aucune action liée aux widgets.</p><p>À partir de la version <strong>Studio 0.1.290</strong>, l&#39;utilisation de la touche <strong>Suppr</strong> (ou <strong>Entf</strong>) sur des widgets sélectionnés ouvre la même boîte de dialogue de suppression que celle utilisée pour la corbeille. Cela s&#39;applique également en cas de sélection multiple. L&#39;annulation ou l&#39;utilisation de la touche <strong>Échap</strong> permet de conserver les widgets ; si la suppression est confirmée, il est possible de la rétablir via la fonction « Annuler ». L&#39;option permettant de désactiver temporairement les demandes de confirmation (pour une durée de cinq minutes) s&#39;applique aussi à la touche <strong>Suppr</strong>. Dans les champs de texte, les boîtes de dialogue ouvertes et lors de l&#39;exécution (Runtime), cette touche ne supprime aucun widget ; maintenir la touche enfoncée ne déclenche pas de demandes supplémentaires.</p><h2 id="widgets-nur-in-der-runtime-ausblenden" tabindex="-1">Masquer des widgets uniquement lors de l&#39;exécution (Runtime) <a class="header-anchor" href="#widgets-nur-in-der-runtime-ausblenden" aria-label="Permalink to &quot;Masquer des widgets uniquement lors de l&#39;exécution (Runtime) {#widgets-nur-in-der-runtime-ausblenden}&quot;">​</a></h2><p>À partir de la version <strong>Studio 0.1.287</strong>, une case à cocher intitulée <strong>Masquer lors de l&#39;exécution</strong> (ou « In Runtime verstecken ») est disponible pour <strong>tous les widgets</strong>, tout en haut de l&#39;onglet <strong>WIDGET</strong>. Cochez cette case et enregistrez le projet : le widget reste visible dans l&#39;éditeur, mais est masqué lors de l&#39;exécution (Runtime). Les calculs et les transferts de valeurs restent actifs (par exemple, depuis un widget de type « Nombre » masqué vers un bloc de calcul). Cette option fonctionne indépendamment de l&#39;indice Z (Z-index). Si la case est décochée, la visibilité normale est rétablie ; les widgets spécifiques liés au flux de données restent, quant à eux, toujours masqués. Les éléments de contrôle masqués ne peuvent pas être cliqués lors de l&#39;exécution.</p><p>À partir de la version <strong>Studio 0.1.286</strong>, l&#39;attribution d&#39;un <strong>indice Z (Z-index) de -100 ou moins</strong> permet de masquer n&#39;importe quel type de widget lors de l&#39;exécution (Runtime). Dans l&#39;éditeur, le widget reste visible et modifiable. Les calculs et le flux de données demeurent actifs ; il est ainsi possible d&#39;utiliser des widgets de type « Nombre », des blocs de calcul (« MathBox ») et leurs connexions comme une chaîne de traitement invisible. Cette règle de masquage spécifique ne s&#39;applique pas si l&#39;indice Z est supérieur ou égal à -99. Un élément de contrôle masqué ne peut pas être cliqué lors de l&#39;exécution.</p><h2 id="seiten-tabs" tabindex="-1">Onglets de pages <a class="header-anchor" href="#seiten-tabs" aria-label="Permalink to &quot;Onglets de pages {#seiten-tabs}&quot;">​</a></h2><p>À partir de la version <strong>0.1.256</strong>, les pages du projet s&#39;affichent sous forme d&#39;onglets compacts, situés directement au-dessus de l&#39;espace de travail, entre la palette de widgets et le panneau des propriétés. Un simple clic permet de changer de page ; la page active est mise en évidence par une couleur. De nombreuses pages défilent horizontalement ; les noms longs sont tronqués, mais leur intitulé complet apparaît dans une info-bulle. Les pages masquées lors de l&#39;exécution (runtime) restent accessibles dans l&#39;éditeur ; leur onglet est alors entouré d&#39;un bord en pointillés.</p><p><img src="'+t+'" alt="Pages du projet sous forme d&#39;onglets au-dessus de l&#39;espace de travail"></p><p>Lorsqu&#39;un onglet est sélectionné, les touches <strong>flèche gauche/droite</strong> permettent de passer à la page adjacente, tandis que les touches <strong>Début/Fin</strong> (Pos1/Ende) permettent d&#39;accéder à la première ou à la dernière page. Les modifications apportées aux widgets et non enregistrées sont conservées lors du changement de page ; en revanche, la sélection des widgets et les actions en cours sur les widgets sont réinitialisées. Les noms et l&#39;ordre des pages correspondent à ceux définis dans le menu <strong>Pages</strong>. Les fonctions de création, renommage, duplication, gestion de la visibilité et suppression restent accessibles via ce menu. Ces onglets constituent une aide à la conception dans l&#39;éditeur ; le mode exécution (runtime) continue d&#39;utiliser son système de navigation habituel.</p><h2 id="einstieg" tabindex="-1">Prise en main <a class="header-anchor" href="#einstieg" aria-label="Permalink to &quot;Prise en main {#einstieg}&quot;">​</a></h2><p>À partir de la version <strong>0.1.184</strong>, des couleurs d&#39;arrière-plan permettent de distinguer les ensembles de widgets dans la palette : <strong>Interactif</strong> est vert olive, <strong>Spécial</strong> est bleu et <strong>Flux de données</strong> est violet. <strong>Base</strong> conserve son apparence actuelle. Les ensembles supplémentaires installés se voient attribuer une couleur spécifique. Ces couleurs s&#39;appliquent aux boutons de sélection de la palette ; la mise en forme des widgets insérés reste, quant à elle, indépendante.</p><p>À partir de la version <strong>0.1.185</strong>, les zones de sélection de tous les ensembles présentent un design plus plat : la hauteur minimale passe de 42 px à 34 px, avec des aperçus de 32 × 26 px. Les libellés restent parfaitement lisibles. L&#39;élément <strong>Dashboard in widget</strong> adopte l&#39;icône standard <code>mdi:view-dashboard</code>.</p><p><img src="'+s+'" alt="Zones de sélection plus plates dans la palette de widgets"></p><p>À partir de la version <strong>0.1.115</strong> de Studio, un clic droit sur un widget, un onglet de groupe ou une zone vide de l&#39;éditeur ouvre un menu contextuel proposant les options suivantes : <strong>Sélectionner</strong>, <strong>Grouper</strong>, <strong>Dissocier</strong>, <strong>Modifier le groupe</strong>, <strong>Copier</strong>, <strong>Couper</strong>, <strong>Coller</strong> et <strong>Supprimer</strong>. La rubrique <strong>Plus</strong> inclut les fonctions : Dupliquer, Premier plan/Arrière-plan, Verrouiller/Déverrouiller, Annuler/Rétablir, ainsi que l&#39;importation/exportation de widgets. Les actions non disponibles apparaissent en grisé ; la touche Échap permet de fermer le menu, tandis que les flèches haut/bas permettent d&#39;y naviguer. L&#39;option « Sélectionner » propose l&#39;ensemble des widgets ainsi que ceux situés sous le curseur de la souris.</p><p>Les groupes conservent les positions relatives de leurs éléments constitutifs ; ainsi, lorsqu&#39;un élément du groupe ou l&#39;onglet du groupe est déplacé, l&#39;ensemble du groupe se déplace en bloc. Ces groupes sont enregistrés dans le projet ; Lorsqu&#39;ils sont collés ou importés, les copies et exportations de plusieurs widgets sélectionnés forment des groupes indépendants. La fonction <strong>Modifier le groupe</strong> permet de modifier les éléments individuellement ; <strong>Terminer la modification du groupe</strong> — ou un clic sur l&#39;onglet du groupe — permet de revenir à la sélection globale. La dissociation (dégroupage) préserve les positions et les dimensions. Les fonctions « Annuler » et « Rétablir » s&#39;appliquent également aux opérations de regroupement et de déplacement. Les groupes sont à structure « plate » ; les lignes de connexion SVG ne peuvent pas être regroupées, et les groupes contenant des éléments verrouillés ne peuvent pas être déplacés par glisser-déposer. En mode exécution (Runtime), ni les cadres de groupe ni le menu d&#39;édition ne sont affichés. Le regroupement ne génère pas de contenu d&#39;onglet et n&#39;importe pas de widgets VIS2.</p><p>Créez un projet dans le menu <strong>Projets</strong> et sélectionnez une page via <strong>Pages</strong>. Définissez la taille de la page, utilisez la <strong>palette de widgets</strong> située à gauche et insérez un élément depuis cette palette. La fonction <strong>Rechercher des widgets</strong>, située en haut de la palette, vous permet de filtrer les widgets disponibles par nom ou par type ; les groupes correspondants s&#39;ouvrent lors de la recherche, sans modifier leur état de déploiement initial. Un clic sur un widget permet de le sélectionner ; ses propriétés s&#39;affichent alors sur la droite. Utilisez <strong>Runtime</strong> pour vérifier l&#39;affichage. La fonction <strong>Enregistrer</strong> permet une sauvegarde manuelle ; les paramètres de sauvegarde automatique (Auto-Save) et son délai peuvent être ajustés sous <strong>Paramètres → Général</strong>. Dans la section <strong>Packs de widgets</strong>, vous pouvez installer un pack local (<code>.wg.zip</code>) à partir de la version 0.1.80. La première interface (0.1) prend en charge des widgets texte validés dotés de propriétés ; les packs installés apparaissent sous forme d&#39;un ensemble distinct dans la palette. Depuis la version 0.1.83, les images des widgets et des packs peuvent être des fichiers SVG ou PNG validés ; en l&#39;absence d&#39;image personnalisée, le symbole texte SVG intégré s&#39;affiche. La suppression est bloquée si un widget issu d&#39;un pack est utilisé dans un projet. À partir de la version 0.1.82, l&#39;onglet <strong>Outils</strong> permet l&#39;installation de packs locaux (<code>.tp.zip</code>). Le premier outil déclaratif affiche un aperçu et, après confirmation, modifie la couleur d&#39;arrière-plan de la page active ; cette modification peut être annulée via la fonction <strong>Annuler</strong>. Les images des outils peuvent également être au format SVG ou PNG ; les boutons du Studio utilisent des symboles SVG. L&#39;installation depuis GitHub ainsi que les mises à jour seront disponibles ultérieurement.</p><p>Dans le sélecteur de widgets situé sur la barre supérieure, vous pouvez sélectionner plusieurs widgets ou annuler la sélection. La barre d&#39;actions propose les fonctions Couper, Copier, Coller, Dupliquer, Supprimer, ainsi que jusqu&#39;à 50 niveaux d&#39;annulation/rétablissement (Undo/Redo). Les dix actions d&#39;alignement s&#39;appliquent à plusieurs widgets standard sélectionnés ; le premier widget sélectionné sert de référence. Pour les paramètres <strong>Largeur</strong> et <strong>Hauteur</strong>, un appui long (environ 0,6 seconde) permet de saisir la valeur souhaitée en pixels.</p><p>L&#39;environnement d&#39;exécution (runtime) centre une page lorsqu&#39;elle tient entièrement dans la fenêtre du navigateur. Pour les pages plus grandes, l&#39;affichage commence en haut à gauche ; des barres de défilement horizontales et verticales permettent d&#39;accéder à l&#39;ensemble de la page, sans modifier les coordonnées des widgets.</p><h2 id="widget-auswahl-kopieren-und-loschen" tabindex="-1">Sélection, copie et suppression de widgets <a class="header-anchor" href="#widget-auswahl-kopieren-und-loschen" aria-label="Permalink to &quot;Sélection, copie et suppression de widgets {#widget-auswahl-kopieren-und-loschen}&quot;">​</a></h2><p>À partir de la version <strong>Studio 0.1.257</strong>, les icônes de la barre d&#39;outils correspondant à <strong>Supprimer</strong>, <strong>Copier</strong> et <strong>Couper</strong> s&#39;activent dès qu&#39;un widget est sélectionné. Si aucun widget n&#39;est sélectionné, ces actions apparaissent grisées ; cela s&#39;applique également lors d&#39;un changement de page. La confirmation de suppression ainsi que la fonction « Annuler » restent disponibles.</p><p><img src="'+n+'" alt="Liste de sélection de widgets avec dix entrées visibles"></p><p>Dans Studio <strong>0.1.196</strong>, la liste peut contenir dix entrées compactes. Si elle en contient davantage, il est possible de faire défiler le contenu ; les actions situées en haut et en bas restent visibles. Si le nombre d&#39;entrées est inférieur, le menu est plus court. Sur les petits écrans, le nombre de lignes visibles s&#39;adapte à la hauteur disponible.</p><p>Les lignes cochées sélectionnent les widgets correspondants sur l&#39;espace de travail. La liste reste visible pendant cette opération ; les actions <strong>Copier</strong> et <strong>Supprimer</strong> s&#39;appliquent à tous les widgets cochés.</p><p><img src="'+i+'" alt="Déplacement groupé de plusieurs widgets collés"></p><p>Faites glisser l&#39;un des widgets sélectionnés pour déplacer l&#39;ensemble de la sélection, y compris après une opération de copier-coller. Les connexions et les points intermédiaires sélectionnés se déplacent également ; la présence de widgets verrouillés empêche le déplacement groupé. La fonction « Annuler » permet de revenir en arrière sur cette action.</p><p><img src="'+r+'" alt="Confirmation de suppression avec option de masquage pendant cinq minutes"></p><p>Cliquez sur <strong>Annuler</strong> ou appuyez sur la touche Échap pour interrompre la suppression. La case à cocher permet de masquer les futures demandes de confirmation pendant cinq minutes au cours de la session d&#39;édition actuelle. Les widgets supprimés peuvent toujours être récupérés via la fonction « Annuler ».</p><h2 id="dateien-und-bildauswahl" tabindex="-1">Fichiers et sélection d&#39;images <a class="header-anchor" href="#dateien-und-bildauswahl" aria-label="Permalink to &quot;Fichiers et sélection d&#39;images {#dateien-und-bildauswahl}&quot;">​</a></h2><p><img src="'+o+'" alt="Recherche de fichiers sous le dossier racine de Studio"></p><p>Le dossier racine est <strong>/config/www/studio</strong>. Studio tente de le créer automatiquement ; toute absence de droits d&#39;écriture sera signalée. La sélection d&#39;images pour les widgets utilise également ce dossier ; les chemins publics commencent par <strong>/local/studio/</strong>. La recherche prend en compte tous les sous-dossiers, ainsi que les noms de fichiers et les chemins d&#39;accès, sans distinction entre majuscules et minuscules. Si le champ de recherche est vide, le dossier actuellement ouvert s&#39;affiche à nouveau. Il est possible de sélectionner des images, y compris des fichiers GIF. La navigation vers le dossier parent reste limitée au périmètre de ce dossier racine.</p><h2 id="sprache-der-oberflache" tabindex="-1">Langue de l&#39;interface <a class="header-anchor" href="#sprache-der-oberflache" aria-label="Permalink to &quot;Langue de l&#39;interface {#sprache-der-oberflache}&quot;">​</a></h2><p>Accédez à <strong>Paramètres → Général → Langue → Langue de l&#39;application</strong>, sélectionnez une option et cliquez sur <strong>Enregistrer</strong> :</p><table tabindex="0"><thead><tr><th>Sélection</th><th>Affichage</th></tr></thead><tbody><tr><td><strong>Automatique (Home Assistant)</strong></td><td>Allemand si Home Assistant est configuré en allemand ; anglais pour toute autre langue. Si la langue de Home Assistant n&#39;est pas détectable, la langue du navigateur est utilisée, avec la même logique de repli (allemand/anglais).</td></tr><tr><td><strong>Allemand</strong></td><td>L&#39;interface reste en allemand.</td></tr><tr><td><strong>Anglais</strong></td><td>L&#39;interface reste en anglais.</td></tr></tbody></table><p>Ce choix ne s&#39;applique qu&#39;au navigateur actuel et est conservé après un rechargement de la page. Les autres utilisateurs et navigateurs conservent leurs propres paramètres. La langue affecte les éléments de l&#39;interface tels que les menus, les boîtes de dialogue, la palette de widgets et les propriétés ; en revanche, les noms de projets et de widgets définis par l&#39;utilisateur, ainsi que le contenu des widgets, ne sont pas traduits.</p><h2 id="tastatur-und-maus" tabindex="-1">Clavier et souris <a class="header-anchor" href="#tastatur-und-maus" aria-label="Permalink to &quot;Clavier et souris {#tastatur-und-maus}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Manipulation</th></tr></thead><tbody><tr><td>Annuler</td><td><code>Strg+Z</code> (macOS : <code>⌘+Z</code>)</td></tr><tr><td>Rétablir</td><td><code>Strg+Y</code> ou <code>Strg+Umschalt+Z</code> (macOS : <code>⌘+Y</code> ou <code>⌘+Umschalt+Z</code>)</td></tr><tr><td>Ajouter ou retirer un widget d&#39;une sélection multiple</td><td>Maintenir <code>Strg+Umschalt</code> enfoncé et cliquer sur le widget</td></tr><tr><td>Déplacer un point d&#39;extrémité libre d&#39;une connexion</td><td>Faire glisser le point avec la souris ; déplacer le point sélectionné par incréments de 1 pixel à l&#39;aide des touches fléchées</td></tr><tr><td>Déplacer un point de ligne plus rapidement</td><td>Maintenir <code>Umschalt</code> tout en appuyant sur une touche fléchée : déplacement par incréments de 10 pixels</td></tr><tr><td>Détacher un point de ligne ancré</td><td>Maintenir <code>Strg</code> et faire glisser le point ; également possible en utilisant <code>Strg</code> combiné à une touche fléchée</td></tr><tr><td>Déplacer une ligne de connexion entière</td><td>Faire glisser une ligne libre ; pour une ligne ancrée, maintenir <code>Alt</code> et faire glisser. Les ancrages existants sont alors supprimés. Le déplacement des poignées de points individuels ne déplace pas une sélection multiple ; le glissement s&#39;active après un déplacement de 6 px.</td></tr><tr><td>Insérer un point intermédiaire ou un point de regroupement</td><td>Cliquer sur la ligne, sélectionner « Point intermédiaire » ou « Point de regroupement » et valider par <strong>OK</strong></td></tr></tbody></table><p>Les raccourcis pour « Annuler » et « Rétablir » s&#39;appliquent lorsque le focus n&#39;est pas placé dans un champ de saisie, une zone de texte ou un champ de sélection. Des boutons sont disponibles pour les fonctions « Couper », « Copier » et « Coller » ; aucun raccourci global <code>Strg+X/C/V</code> n&#39;est actuellement défini pour ces actions.</p><h2 id="verbindungslinien-und-andockpunkte" tabindex="-1">Lignes de connexion et points d&#39;ancrage <a class="header-anchor" href="#verbindungslinien-und-andockpunkte" aria-label="Permalink to &quot;Lignes de connexion et points d&#39;ancrage {#verbindungslinien-und-andockpunkte}&quot;">​</a></h2><p>Activez les <strong>points d&#39;ancrage</strong> dans les propriétés d&#39;un widget cible. Pour les nouveaux widgets, tous les points sont désactivés. L&#39;option <strong>Tous les points</strong> permet d&#39;activer simultanément les douze positions ; des points individuels peuvent ensuite être ajustés. La case à cocher du groupe active ou désactive l&#39;ensemble de la zone. Les extrémités d&#39;une connexion SVG peuvent être déplacées vers des points actifs. Un point intermédiaire divise le tracé en segments supplémentaires ; seul un <strong>point de connexion</strong> (sammelpunkt) explicitement activé peut servir de point de raccordement pour d&#39;autres lignes. Un simple croisement ne relie pas les lignes entre elles. Pour la représentation visuelle, plusieurs options sont disponibles, notamment : lignes, tracés en zigzag ou à points multiples, couleurs, épaisseur, pointes de flèches, animations et gestion de l&#39;ordre d&#39;empilement (z-index).</p><h2 id="sichtbarkeit-und-filter" tabindex="-1">Visibilité et filtres <a class="header-anchor" href="#sichtbarkeit-und-filter" aria-label="Permalink to &quot;Visibilité et filtres {#sichtbarkeit-und-filter}&quot;">​</a></h2><p>Les sections <strong>Général</strong> et <strong>Visibilité</strong> sont présentes sur chaque widget et sont désactivées par défaut. La section « Général » comprend, entre autres, le nom, un commentaire, une classe CSS, un mot-clé de filtrage et une option de verrouillage. Le filtre de l&#39;éditeur permet de masquer des widgets en fonction de ce mot-clé ou, au contraire, de n&#39;afficher que les éléments correspondants. En phase d&#39;exécution (runtime), la visibilité peut être conditionnée par l&#39;état d&#39;une entité Home Assistant, en utilisant une condition et une valeur de comparaison ; l&#39;évaluation par groupe n&#39;est pas encore implémentée.</p>',46)])])}const w=a(c,[["render",p]]);export{x as __pageData,w as default};
